// Service worker, generated by scripts/build_pwa.py from scripts/sw.template.js.
// The version below changes whenever the app shell changes, which is how the
// browser notices an update (it compares this file byte for byte).
const VERSION = "__VERSION__";
const SHELL = `shell-${VERSION}`;
const DATA = "data-v1";      // chapters, lexicons, indexes: kept across versions
const FONTS = "fonts-v1";
const LIVE = "live-v1";      // Sefaria API responses (network first)

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const res = await fetch("precache.json", { cache: "no-store" });
    const { files } = await res.json();
    const cache = await caches.open(SHELL);
    await cache.addAll(files.map((f) => new Request(f, { cache: "reload" })));
  })());
  // No skipWaiting here: the page asks the user before switching versions.
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith("shell-") && key !== SHELL) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener("message", (event) => {
  if (event.data === "skipWaiting") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin === location.origin) {
    if (req.mode === "navigate") {
      // Hash routing: every page is index.html.
      event.respondWith(caches.match("index.html", { cacheName: SHELL }).then((r) => r || fetch(req)));
    } else if (url.pathname.includes("/data/")) {
      event.respondWith(dataFirstFromCache(event, req));
    } else {
      event.respondWith(caches.match(req, { cacheName: SHELL }).then((r) => r || fetch(req)));
    }
  } else if (url.hostname.endsWith("fonts.googleapis.com") || url.hostname.endsWith("fonts.gstatic.com")) {
    event.respondWith(cacheFirst(FONTS, req));
  } else if (url.hostname.endsWith("sefaria.org")) {
    event.respondWith(networkFirst(LIVE, req));
  }
});

// Data: shell copy if precached, else stale-while-revalidate in the data cache,
// so downloaded and visited chapters work offline and refresh quietly online.
async function dataFirstFromCache(event, req) {
  const shell = await caches.match(req, { cacheName: SHELL });
  if (shell) return shell;
  const cache = await caches.open(DATA);
  const cached = await cache.match(req);
  const update = fetch(req).then((res) => {
    if (res.ok) cache.put(req, res.clone());
    return res;
  });
  if (cached) {
    event.waitUntil(update.catch(() => {}));
    return cached;
  }
  return update;
}

async function cacheFirst(name, req) {
  const cache = await caches.open(name);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok || res.type === "opaque") cache.put(req, res.clone());
  return res;
}

async function networkFirst(name, req) {
  const cache = await caches.open(name);
  try {
    const res = await fetch(req);
    if (res.ok) cache.put(req, res.clone());
    return res;
  } catch (err) {
    const hit = await cache.match(req);
    if (hit) return hit;
    throw err;
  }
}
